ON DUPLICATE KEY UPDATE product_id=VALUES(product_id), location_id=VALUES(location_id), plan_qty=VALUES(plan_qty), received_qty=VALUES(received_qty), qualified_qty=VALUES(qualified_qty), deleted=0, updated_at=NOW(3);
