ON DUPLICATE KEY UPDATE product_id=VALUES(product_id), location_id=VALUES(location_id), plan_qty=VALUES(plan_qty), picked_qty=VALUES(picked_qty), shipped_qty=VALUES(shipped_qty), deleted=0, updated_at=NOW(3);
ON DUPLICATE KEY UPDATE biz_type=VALUES(biz_type), biz_no=VALUES(biz_no), change_qty=VALUES(change_qty), before_qty=VALUES(before_qty), after_qty=VALUES(after_qty), occurred_at=VALUES(occurred_at), deleted=0, updated_at=NOW(3);

-- =========================
-- Customer Service Demo Data
-- =========================
ON DUPLICATE KEY UPDATE channel=VALUES(channel), customer_id=VALUES(customer_id), status=VALUES(status), assigned_user_id=VALUES(assigned_user_id), priority=VALUES(priority), first_response_at=VALUES(first_response_at), closed_at=VALUES(closed_at), created_at=VALUES(created_at), deleted=0, updated_at=NOW(3);
ON DUPLICATE KEY UPDATE sender_type=VALUES(sender_type), sender_id=VALUES(sender_id), content=VALUES(content), msg_type=VALUES(msg_type), ai_suggested=VALUES(ai_suggested), created_at=VALUES(created_at), deleted=0, updated_at=NOW(3);
ON DUPLICATE KEY UPDATE session_id=VALUES(session_id), priority=VALUES(priority), content=VALUES(content), status=VALUES(status), created_at=VALUES(created_at), deleted=0, updated_at=NOW(3);
ON DUPLICATE KEY UPDATE question=VALUES(question), answer=VALUES(answer), tags=VALUES(tags), scene=VALUES(scene), priority=VALUES(priority), enabled=VALUES(enabled), version_no=VALUES(version_no), deleted=0, updated_at=NOW(3);

-- =========================
-- AI Demo Conversations
-- =========================
ON DUPLICATE KEY UPDATE scene=VALUES(scene), biz_type=VALUES(biz_type), biz_no=VALUES(biz_no), provider_type=VALUES(provider_type), model_name=VALUES(model_name), status=VALUES(status), started_at=VALUES(started_at), ended_at=VALUES(ended_at), created_at=VALUES(created_at), deleted=0, updated_at=NOW(3);
ON DUPLICATE KEY UPDATE role=VALUES(role), content=VALUES(content), tokens=VALUES(tokens), latency_ms=VALUES(latency_ms), confidence=VALUES(confidence), error_code=VALUES(error_code), created_at=VALUES(created_at), deleted=0, updated_at=NOW(3);

-- =========================
-- Post-fix text normalization (avoid mojibake in Windows shells)
-- =========================
UPDATE tenants
SET tenant_name = 'NovaDepot Demo Tenant'
WHERE id = 1;

UPDATE roles
SET role_name = CASE role_code
  WHEN 'TENANT_ADMIN' THEN 'Admin'
  WHEN 'WAREHOUSE_MANAGER' THEN 'Warehouse Manager'
  WHEN 'WAREHOUSE_OPERATOR' THEN 'Warehouse Operator'
  WHEN 'CS_AGENT' THEN 'Customer Service Agent'
  WHEN 'DATA_VIEWER' THEN 'Read Only Viewer'
  ELSE role_name END
WHERE tenant_id = 1;

UPDATE users
SET real_name = CASE username
  WHEN 'admin' THEN 'System Admin'
  WHEN 'warehouse01' THEN 'Warehouse Operator'
  WHEN 'operator' THEN 'Warehouse Operator'
  WHEN 'cs01' THEN 'Customer Service Operator'
  WHEN 'observer01' THEN 'Data Viewer'
  ELSE real_name END
WHERE tenant_id = 1;

UPDATE permissions
SET perm_name = perm_code
WHERE id BETWEEN 3001 AND 3077;

UPDATE product_categories
SET category_name = CASE category_code
  WHEN 'CAT-FOOD' THEN 'Food'
  WHEN 'CAT-HOUSE' THEN 'Household'
  WHEN 'CAT-3C' THEN '3C Electronics'
  WHEN 'CAT-OFFICE' THEN 'Office'
  ELSE category_name END
WHERE tenant_id = 1;

UPDATE product_units
SET unit_name = CASE unit_code
  WHEN 'PCS' THEN 'Piece'
  WHEN 'BOX' THEN 'Box'
  ELSE unit_name END
WHERE tenant_id = 1;

UPDATE warehouses
SET warehouse_name = CASE id
  WHEN 11001 THEN JSON_UNQUOTE('\"\\u4e00\\u53f7\\u4ed3\"')
  WHEN 11002 THEN JSON_UNQUOTE('\"\\u4e8c\\u53f7\\u4ed3\"')
  WHEN 11003 THEN JSON_UNQUOTE('\"\\u4e09\\u53f7\\u4ed3\"')
  ELSE warehouse_name END,
    address = CASE id
  WHEN 11001 THEN 'Shanghai Pudong Logistics Park 88'
  WHEN 11002 THEN 'Hangzhou Binjiang E-commerce Hub 18'
  WHEN 11003 THEN 'Shenzhen Baoan Returns Center 66'
  ELSE address END
WHERE tenant_id = 1;

UPDATE warehouse_locations
SET location_name = CONCAT(
  (SELECT w.warehouse_name FROM warehouses w WHERE w.id = warehouse_locations.warehouse_id),
  '-',
  JSON_UNQUOTE('\"\\u5e93\\u4f4d\"'),
  LPAD(((id - 12001) % 16) + 1, 2, '0')
)
WHERE tenant_id = 1;

UPDATE products
SET product_name = CONCAT(JSON_UNQUOTE('\"\\u5546\\u54c1\"'), LPAD(id - 13000, 3, '0')),
    spec = CONCAT('Spec-', LPAD(id - 13000, 3, '0'), '; MSRP=', ROUND((12 + ((id - 13000) % 19)) * 3.5, 2))
WHERE tenant_id = 1;

UPDATE inbound_orders
SET remark = CONCAT('Inbound order ', inbound_no, ' for purchase receiving.')
WHERE tenant_id = 1;

UPDATE outbound_orders
SET remark = CONCAT('Outbound order ', outbound_no, ' for sales shipment.')
WHERE tenant_id = 1;

UPDATE customer_service_messages
SET content = CONCAT('Customer service conversation ', session_id, ' message #', id)
WHERE tenant_id = 1;

UPDATE customer_service_tickets
SET content = CONCAT('Ticket for session ', session_id, ': order and fulfillment follow-up.')
WHERE tenant_id = 1;

UPDATE faq_knowledge
SET question = CONCAT('FAQ Q', LPAD(id - 6000, 3, '0'), ': How to handle order and warehouse issue.'),
    answer = CONCAT('FAQ A', LPAD(id - 6000, 3, '0'), ': Please follow SOP, check status and create ticket if needed.'),
    tags = 'demo,faq,ops'
WHERE tenant_id = 1;

UPDATE ai_messages
SET content = CASE role
  WHEN 'USER' THEN 'Please analyze inventory risk and replenishment priority.'
  ELSE 'Suggested: prioritize low stock SKUs, review in-transit stock, and schedule replenishment.'
END
WHERE tenant_id = 1;


